      visibleTiles.push(t);
    }
    visibleTiles.sort((a, b) => {
      const ax = (a.tx + 0.5) * a.blocks - v.cam.x;
      const az = (a.tz + 0.5) * a.blocks - v.cam.z;
      const bx = (b.tx + 0.5) * b.blocks - v.cam.x;
      const bz = (b.tz + 0.5) * b.blocks - v.cam.z;
      return (ax * ax + az * az) - (bx * bx + bz * bz);
