  }

  function enumerateDense() {
    const area = rect(160);
    const cam = view().cam;
    const cx0 = Math.floor(area.x0 / DENSE_CELL);
    const cx1 = Math.floor(area.x1 / DENSE_CELL);
    const cz0 = Math.floor(area.z0 / DENSE_CELL);
    const cz1 = Math.floor(area.z1 / DENSE_CELL);
