    for (let cz = cz0; cz <= cz1; cz++) {
      for (let cx = cx0; cx <= cx1; cx++) {
        const key = cx + "|" + cz;
        if (dense.done.has(key) || dense.queued.has(key)) continue;
        dense.queued.add(key);
        const x0 = cx * DENSE_CELL, z0 = cz * DENSE_CELL;
