    let step = null;
    try {
      step = job.advance(12);
    } catch (err) {
      state.strongholdJob = null;
      console.error(err);
      return;
    }
    if (step.pos) {
      addStructure("stronghold", step.pos.x, step.pos.z);
      onChange();
