(function (global) {
  "use strict";

  const U = global.SeedMapUtil;
  const formatInt = U.formatInt;
  const FONT_MONO = 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace';
  const TAU = Math.PI * 2;

  const state = { active: false, points: [] };

  let ctx = null;
  let view = null;
  let rootEl = null;
  let onChange = function () {};
  let panelEl = null;
  let btnEl = null;
  let clearEl = null;
  let countEl = null;
  let totalEl = null;
  let timeEl = null;
  let routeEl = null;

  function screen(p) {
    const v = view();
    return {
      x: v.vw / 2 + (p.x - v.cam.x) * v.cam.s,
