      const d = Math.hypot(pts[i].x - pts[i - 1].x, pts[i].z - pts[i - 1].z);
      const mid = { x: (screens[i].x + screens[i - 1].x) / 2, y: (screens[i].y + screens[i - 1].y) / 2 };
