    planResultEl.hidden = false;
    if (plan.notFound) {
      planResultEl.appendChild(el("h3", null, "No roll found"));
      planResultEl.appendChild(el("p", "plan-empty", plan.notFound));
      return;
    }
    planResultEl.appendChild(el("h3", null,
      plan.thrown === -1 ? "No dummy enchant needed" :
      plan.thrown === 0 ? "Enchant one dummy first" :
      "Throw " + plan.thrown + " item" + (plan.thrown === 1 ? "" : "s") + ", then one dummy"));
    planResultEl.appendChild(el("p", "plan-big", ENCH.SLOT_NAMES[plan.slot] + " · " + plan.shelves + " shelves"));
    planResultEl.appendChild(el("p", "plan-sub",
      "Level " + plan.offer.level + " offer · costs " + (plan.slot + 1) +
      (plan.slot ? " levels" : " level") + (plan.dummy ? " plus 1 for the dummy" : "") +
      " · " + plan.levelsAfter + " left"));
    const steps = el("ol", "plan-steps");
    for (const text of planSteps(plan)) steps.appendChild(el("li", null, text));
    planResultEl.appendChild(steps);

    const stats = el("dl", "plan-stats");
    stats.appendChild(stat("XP seed", formatXp(plan.xpSeed) + " → " + formatXp(ENCH.xpFromSeed(plan.seedAfter))));
    stats.appendChild(stat("Enchantment seed after", formatPlayerSeed(plan.seedAfter)));
    stats.appendChild(stat("Items to throw", plan.thrown === -1 ? "None" : String(plan.thrown)));
    stats.appendChild(stat("Levels after", String(plan.levelsAfter)));
    planResultEl.appendChild(stats);

    planResultEl.appendChild(el("p", "plan-sub", "This offer contains " +
      plan.offer.spells.map((s) => ENCH.spellLabel(s.id, s.level)).join(", ") + "."));

    const actions = el("div", "plan-actions");
    const apply = el("button", "btn-secondary", "Mark this roll as used");
    apply.type = "button";
    apply.addEventListener("click", () => {
      state.playerSeed = plan.seedAfter;
      state.level = Math.max(1, plan.levelsAfter);
      state.plan = null;
      renderPlan();
      refresh();
    });
    actions.appendChild(apply);
    planResultEl.appendChild(actions);
  }

  function findRoll() {
    if (state.playerSeed === null || !state.wanted.size) {
      updateNote();
      return;
    }
    const mat = material();
    state.plan = ENCH.searchPlan({
      playerSeed: state.playerSeed,
      itemId: state.item,
      materialId: mat ? mat.id : "",
      maxShelves: 15,
      playerLevel: state.level,
      wanted: Array.from(state.wanted, ([id, level]) => ({ id, level })),
      maxThrows: 512,
    });
    if (!state.plan) {
      state.plan = { notFound: "No offer with those enchantments appeared in the first 512 item throws. Lower a tier, choose fewer enchantments, or add player levels." };
      renderPlan();
    } else {
      renderPlan();
      renderOffers();
    }
  }

  /* ---------------------------------------------------------------- seeds */

  function markField(input, valid) {
    input.closest(".seed-field").classList.toggle("is-invalid", !valid);
  }

  function rerender() {
    state.plan = null;
    renderPlan();
    renderOffers();
    updateNote();
  }

  function setPlayerSeedFromInput() {
    const seed = parsePlayerSeed(playerSeedEl.value);
    markField(playerSeedEl, seed !== null);
    // An unreadable seed clears the table instead of leaving stale offers.
    state.playerSeed = seed;
    rerender();
  }

  function setWorldSeedFromInput() {
    state.worldSeed = worldSeedEl.value;
    const seed = playerSeedFromWorld(state.worldSeed);
    markField(worldSeedEl, seed !== null);
    if (seed === null) return;
    state.playerSeed = seed;
    if (document.activeElement !== playerSeedEl) playerSeedEl.value = formatPlayerSeed(seed);
    rerender();
  }

  /* ------------------------------------------------------------- lifecycle */

  function open(worldSeedText) {
    if (state.open) return;
    state.open = true;
    const typed = String(worldSeedText || "").trim() || "0";
    const world = playerSeedFromWorld(typed) === null ? "0" : typed;
    // Keep a seed that was rolled forward in this session; a new home seed
    // re-derives the starting state instead.
    if (state.playerSeed === null || world !== state.worldSeed) {
      state.worldSeed = world;
      state.playerSeed = playerSeedFromWorld(world);
    }
    state.plan = null;
    sectionEl.hidden = false;
    sectionEl.querySelector(".calc-page").scrollTop = 0;
    renderPlan();
    refresh();
    requestAnimationFrame(() => sectionEl.focus({ preventScroll: true }));
  }

  function close() {
    if (!state.open) return;
    state.open = false;
    sectionEl.hidden = true;
    onClose();
  }

  function keydown(e) {
    if (e.key !== "Escape") return true;
    e.preventDefault();
    close();
    return true;
  }

  /* ------------------------------------------------------------------ init */

  function init(opts) {
    onClose = (opts && opts.onClose) || function () {};
    const mount = document.getElementById("calcMount");
    mount.innerHTML = MARKUP;

    sectionEl = document.getElementById("enchant");
    backBtn = document.getElementById("enchantBack");
    itemsEl = document.getElementById("enchantItems");
    materialsEl = document.getElementById("enchantMaterials");
    gearMetaEl = document.getElementById("enchantGearMeta");
    playerSeedEl = document.getElementById("calcPlayerSeed");
    worldSeedEl = document.getElementById("calcWorldSeed");
    offersEl = document.getElementById("calcOffers");
    wantedEl = document.getElementById("calcWanted");
    levelEl = document.getElementById("calcLevel");
    planBtn = document.getElementById("calcPlanBtn");
    planNoteEl = document.getElementById("calcPlanNote");
    planResultEl = document.getElementById("calcPlanResult");
    wantedClearBtn = document.getElementById("calcWantedClear");

    buildGear();
    buildMaterials();
    buildWanted();

    backBtn.addEventListener("click", close);
    playerSeedEl.addEventListener("input", setPlayerSeedFromInput);
    playerSeedEl.addEventListener("blur", () => {
      if (state.playerSeed !== null) playerSeedEl.value = formatPlayerSeed(state.playerSeed);
    });
    worldSeedEl.addEventListener("input", setWorldSeedFromInput);
    levelEl.addEventListener("input", () => {
      state.level = clamp(Math.round(Number(levelEl.value) || 1), 1, 100);
      updateNote();
    });
    planBtn.addEventListener("click", findRoll);
    wantedClearBtn.addEventListener("click", () => {
      state.wanted.clear();
      state.plan = null;
      buildWanted();
      renderPlan();
    });
  }

  global.SeedMapCalc = {
    init,
    open,
    close,
    keydown,
    isOpen: () => state.open,
    item: () => state.item,
    material: () => (material() ? material().id : ""),
    worldSeed: () => state.worldSeed,
    playerSeed: () => (state.playerSeed === null ? null : formatPlayerSeed(state.playerSeed)),
    xpSeed: () => formatXp(ENCH.xpFromSeed(state.playerSeed === null ? 0n : state.playerSeed)),
    table: () => ENCH.table(state.playerSeed === null ? 0n : state.playerSeed, state.item,
      material() ? material().id : ""),
    plan: () => state.plan,
  };
})(typeof window !== "undefined" ? window : globalThis);

/* Application shell: home flow, page transitions and the debug handle. */
(function () {
  "use strict";

  const E = window.SeedMapEngine;
  const MAP = window.SeedMapMap;
  const CALC = window.SeedMapCalc;

  const HOME_TITLE = "Seedmap — offline Minecraft seed atlas";

  const app = {
    mapShown: false,
    world: null,
    seedText: "",
    homeTimer: 0,
  };

  let rootEl = null;
  let homeEl = null;
  let mapUiEl = null;
  let seedForm = null;
  let seedInput = null;
  let enchantBtn = null;

  /* ---------------------------------------------------------- transitions */

  function hideHome() {
    homeEl.classList.add("is-out");
    homeEl.setAttribute("aria-hidden", "true");
    homeEl.setAttribute("inert", "");
    clearTimeout(app.homeTimer);
    app.homeTimer = setTimeout(() => {
      if (homeEl.classList.contains("is-out")) homeEl.hidden = true;
    }, 320);
  }

  function showHome(seedText) {
    clearTimeout(app.homeTimer);
    if (seedText) app.seedText = seedText;
    homeEl.hidden = false;
    homeEl.classList.remove("is-out");
    homeEl.removeAttribute("aria-hidden");
    homeEl.removeAttribute("inert");
    seedInput.disabled = false;
    seedInput.value = app.seedText;
    rootEl.classList.remove("map-mode");
    document.title = HOME_TITLE;
    if (window.matchMedia && window.matchMedia("(pointer: fine)").matches) {
      setTimeout(() => { seedInput.focus(); seedInput.select(); }, 120);
    }
  }

  /* ------------------------------------------------------------ map flow */

  function shakeInput() {
    const line = seedInput.parentElement;
    line.classList.remove("shake");
    void line.offsetWidth;
    line.classList.add("shake");
    seedForm.classList.add("invalid");
    seedInput.focus();
  }

  function startMap(text) {
    if (app.mapShown || CALC.isOpen()) return false;
    const parsed = E.parseSeed(text);
    if (!parsed) { shakeInput(); return false; }
    try {
      app.world = new E.World(parsed.text, parsed.seed);
    } catch (err) {
      console.error("Seed generation failed", err);
      return false;
    }
    app.seedText = parsed.text;
    seedInput.blur();
    seedInput.disabled = true;
    app.mapShown = true;
    hideHome();
    mapUiEl.hidden = false;
    rootEl.classList.add("map-mode");
    document.title = parsed.text + " — seedmap";
    MAP.show(app.world, parsed.text);
    return true;
  }

  function goHome() {
    if (!app.mapShown) return;
    app.mapShown = false;
    MAP.hide();
    mapUiEl.hidden = true;
    showHome();
  }

  function openCalc() {
    if (app.mapShown || CALC.isOpen()) return;
    hideHome();
    CALC.open(seedInput.value);
    document.title = "Enchanting table — seedmap";
  }

  function closeCalc() {
    // Carry the seed the calculator ended on back to the seed box.
    showHome(CALC.worldSeed().trim());
  }

  /* --------------------------------------------------------------- keyboard */

  function onKeyDown(e) {
    if (CALC.isOpen()) {
      CALC.keydown(e);
      return;
    }
    if (!app.mapShown) return;
    if (!MAP.keydown(e)) {
      e.preventDefault();
      goHome();
    }
  }

  /* -------------------------------------------------------------------- init */

  function init() {
    rootEl = document.getElementById("root");
    homeEl = document.getElementById("home");
    mapUiEl = document.getElementById("mapUi");
    seedForm = document.getElementById("seedForm");
    seedInput = document.getElementById("seedInput");
    enchantBtn = document.getElementById("enchantBtn");

    MAP.init({ onExit: goHome });
    CALC.init({ onClose: closeCalc });

    seedForm.addEventListener("submit", (e) => {
      e.preventDefault();
      startMap(seedInput.value);
    });
    seedInput.addEventListener("keydown", (e) => {
      if (e.key !== "Enter") return;
      e.preventDefault();
      startMap(seedInput.value);
    });
    seedInput.addEventListener("input", () => seedForm.classList.remove("invalid"));
    enchantBtn.addEventListener("click", openCalc);
    window.addEventListener("keydown", onKeyDown);

    if (window.matchMedia && window.matchMedia("(pointer: fine)").matches) {
      setTimeout(() => {
        if (!CALC.isOpen() && !app.mapShown) seedInput.focus();
      }, 250);
    }

    // A small debug handle keeps automated verification honest without
    // adding UI.
    window.__seedmap = {
      start: (s) => { seedInput.value = s; return startMap(s); },
      home: goHome,
      get seed() { return app.seedText; },
      get mapShown() { return app.mapShown; },
      get scale() { return MAP.scale(); },
      get center() { return MAP.center(); },
      get tiles() { return MAP.stats().tiles; },
      get readyTiles() { return MAP.stats().readyTiles; },
      get structures() { return MAP.stats().structures; },
      get strongholds() { return MAP.stats().strongholds; },
      get pendingStrongholds() { return MAP.stats().pendingStrongholds; },
      get pendingStructures() { return MAP.stats().pendingStructures; },
      get pendingDense() { return MAP.stats().pendingDense; },
      get denseCells() { return MAP.stats().denseCells; },
      get pointers() { return MAP.stats().pointers; },
      get markers() { return MAP.markers(); },
      get points() { return MAP.points(); },
      get distance() { return MAP.distance(); },
      get measureActive() { return MAP.isMeasuring(); },
      get keyOpen() { return MAP.keyOpen(); },
      get gridStep() { return MAP.gridStep(); },
      get markerSize() { return MAP.markerSize(); },
      get enchantOpen() { return CALC.isOpen(); },
      get enchant() {
        return {
          item: CALC.item(),
          material: CALC.material(),
          worldSeed: CALC.worldSeed(),
          playerSeed: CALC.playerSeed(),
          xpSeed: CALC.xpSeed(),
          table: CALC.table(),
          plan: CALC.plan(),
        };
      },
      openEnchant: openCalc,
      closeEnchant: closeCalc,
      measure: (on) => MAP.setMeasuring(on === undefined ? !MAP.isMeasuring() : on),
      clearMeasure: MAP.clearMeasure,
      addPoint: (x, z) => MAP.addPoint(x, z),
      screenToWorld: (x, y) => MAP.screenToWorld(x, y),
      biomeAt: (x, z) => MAP.biomeAt(x, z),
      zoom: (f) => MAP.zoom(f),
      pan: (dx, dz) => MAP.pan(dx, dz),
    };
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
